"""Solution, laboratory and evidence content shared by both languages."""
def pick(d,tr,en): return en if d['home']=='Home' else tr
for lang,d in COPY.items():
 en=lang=='en'
 d['contactoptions'].insert(2, ('Laboratory services','Discuss microarray and long-read sequencing for longevity.','Geniva laboratory services') if en else ('Laboratuvar hizmetleri','Longevity için microarray ve uzun okuma dizileme çalışmalarını konuşalım.','Geniva laboratuvar hizmetleri'))
 d['nav'].append('References' if en else 'Referanslar')
 d['titles']['references']='References | Geniva' if en else 'Referanslar | Geniva'
 d['aboutparagraphs'][1]=('We bring together the Gennext platform, on-site computing infrastructure, laboratory services and medical genomics training. Our multi-omics approach considers genomic, transcriptomic, epigenetic, metabolomic and lipidomic data in a shared biological context.' if en else 'Gennext platformunu, kurum içi hesaplama altyapısını, laboratuvar hizmetlerini ve tıbbi genomik eğitimlerini birbirini tamamlayan çalışma alanları olarak ele alıyoruz. Multiomik yaklaşımımız; genomik, transkriptomik, epigenetik, metabolomik ve lipidomik verileri ortak bir biyolojik bağlamda değerlendirmeye dayanır.')
 d['aboutdesc']=('Geniva brings software, infrastructure and laboratory expertise together for genomic analysis. Our scientific approach also encompasses transcriptomics, epigenetics, metabolomics and lipidomics.' if en else 'Geniva olarak genomik analiz için yazılım, altyapı ve laboratuvar deneyimini bir araya getiriyoruz. Bilimsel yaklaşımımız transkriptomik, epigenetik, metabolomik ve lipidomik verileri de kapsıyor.')
 d['omicsdesc']=('DNA, RNA, epigenetic marks, metabolites and lipids reveal different aspects of biology. We consider these layers together around the question each study seeks to answer.' if en else 'DNA, RNA, epigenetik işaretler, metabolitler ve lipitler biyolojinin farklı yönlerini yansıtır. Bu katmanları, çalışmanın yanıt aradığı soru etrafında birlikte değerlendiriyoruz.')
 d['omicslayers'] += [('METABOLITES' if en else 'METABOLİTLER','Metabolomics' if en else 'Metabolomik','Small molecules reflecting metabolic processes.' if en else 'Metabolik süreçleri yansıtan küçük moleküller.'),('LIPIDS' if en else 'LİPİTLER','Lipidomics' if en else 'Lipidomik','Lipid composition and biological relationships.' if en else 'Lipitlerin bileşimi ve biyolojik ilişkileri.')]
 d['softwarebody']=('We analyse short-read and long-read sequencing data, from quality control and variant assessment to reporting. Gennext Clinical supports somatic and germline workflows; Gennext Longevity brings genetic and epigenetic findings into professional wellness services.' if en else 'Kısa okuma (short-read) ve uzun okuma (long-read) dizileme verilerini kalite kontrolden varyant değerlendirmeye ve raporlamaya kadar analiz ediyoruz. Gennext Clinical, somatik ve kalıtsal hastalık analizlerine; Gennext Longevity ise genetik ve epigenetik bulguların sağlıklı yaşam hizmetlerinde değerlendirilmesine odaklanır.')
 d['solutionslead']=('Choose analysis and reporting, an institutional computing system, longevity laboratory services or training. We define the scope around your samples, data and intended use.' if en else 'Analiz ve raporlama, kurum içi hesaplama altyapısı, longevity laboratuvar hizmetleri veya eğitim. İhtiyacınıza uygun hizmeti örnekleriniz, verileriniz ve çalışma amacınız üzerinden birlikte belirleyelim.')
 d['productdesc']=('Gennext connects short-read and long-read data processing with variant assessment and reporting for clinical genomics and longevity.' if en else 'Gennext, short-read ve long-read veri analizini varyant değerlendirme ve raporlamayla birleştirir. Klinik genomik ve longevity çalışmalarında kullanılır.')
 d['servicesdesc']=('From sequencing data to a report, from on-site computing to laboratory services: explore what we deliver.' if en else 'Dizileme verisinden rapora, kurum içi analiz sisteminden laboratuvar hizmetine: ihtiyacınız olan çalışma alanını keşfedin.')
PAGES.append('references')
base_header=header
base_home=home
base_about=about

def header(d,lang,page):
 s=base_header(d,lang,page)
 before='<a href="contact.html"'
 idx=s.index(before)
 return s[:idx]+f'<a href="references.html"'+(' aria-current="page"' if page=='references' else '')+f'>{d["nav"][4]}</a>'+s[idx:]

def screen(d,prefix):
 steps=pick(d,[('Veri','Short-read / Long-read'),('Analiz','Kalite kontrol ve işleme'),('Değerlendirme','Varyantlar ve kanıtlar'),('Rapor','Uzman değerlendirmesi')],[('Data','Short-read / Long-read'),('Analysis','Quality control and processing'),('Assessment','Variants and evidence'),('Report','Expert review')])
 cells=''.join(f'<div class="flow-cell"><span class="flow-number">0{i+1}</span><strong>{a}</strong><p>{b}</p><div class="signal-bars" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div></div>' for i,(a,b) in enumerate(steps))
 return f'<figure class="platform-concept"><div class="concept-header"><img src="{prefix}assets/gennext-inverse.svg" width="140" height="52" alt="Gennext"><span>{pick(d,"ANALİZ VE RAPORLAMA","ANALYSIS & REPORTING")}</span></div><div class="concept-flow">{cells}</div><div class="concept-modules"><span>Clinical <small>Somatic · Germline</small></span><span>Longevity <small>{pick(d,"Genetik · Epigenetik","Genetics · Epigenetics")}</small></span></div><figcaption>{pick(d,"Analiz iş akışının kavramsal gösterimi.","Conceptual view of the analysis workflow.")}</figcaption></figure>'

def hardware(d,p):
 return f'<figure class="hardware-photo"><img src="{p}assets/hardware.jpg" alt="{pick(d,"Siyah ASUS AP201 bilgisayar kasası, temsili analiz donanımı","Black ASUS AP201 computer chassis, representative analysis hardware")}" width="1500" height="1500" loading="lazy"><figcaption>{pick(d,"Temsili donanım görseli. Bileşenler ve kapasite kurumun ihtiyacına göre belirlenir.","Representative hardware image. Components and capacity are configured for each institution.")}</figcaption></figure>'

def laboratory(d,p,compact=False):
 labels=pick(d,['Microarray çalışma alanı','Long-read sekanslama alanı'],['Microarray workspace','Long-read sequencing workspace'])
 photos=''.join(f'<figure class="lab-photo-placeholder" data-photo-slot="{key}"><span class="photo-corners" aria-hidden="true">＋</span><figcaption><strong>{label}</strong><small>{pick(d,"Laboratuvar fotoğrafı eklenecek","Laboratory photo coming soon")}</small></figcaption></figure>' for key,label in zip(['microarray','long-read'],labels))
 return f'''<section class="section lab-section" id="laboratory"><div class="container"><div class="section-head"><div><p class="eyebrow">{pick(d,'LONGEVITY LABORATUVARI','LONGEVITY LABORATORY')}</p><h2>{pick(d,'Laboratuvardan<br>kişisel sağlık verisine.','From the laboratory<br>to personal health insights.')}</h2></div><p>{pick(d,'Kendi laboratuvarımızda microarray ve uzun okuma dizileme çalışmaları yürütüyoruz. Bu altyapıyı longevity hizmetlerimizin genetik ve epigenetik değerlendirmelerinde kullanıyoruz.','Our laboratory performs microarray and long-read sequencing work, supporting the genetic and epigenetic assessments within our longevity services.')}</p></div><div class="lab-photos">{photos}</div><div class="lab-capabilities"><article><span>01 / MICROARRAY</span><h3>{pick(d,'Genetik ve epigenetik profilleme','Genetic and epigenetic profiling')}</h3><p>{pick(d,'Genotipleme ve DNA metilasyonu çalışmalarıyla genetik yatkınlık ve epigenetik değerlendirmelere veri sağlıyoruz.','Genotyping and DNA methylation workflows provide data for genetic predisposition and epigenetic assessment.')}</p></article><article><span>02 / LONG-READ</span><h3>{pick(d,'Uzun okuma dizileme','Long-read sequencing')}</h3><p>{pick(d,'Nanopore teknolojisiyle uzun DNA parçalarını diziliyor, elde edilen verileri çalışmanın amacına uygun analiz ediyoruz.','We sequence long DNA fragments with Nanopore technology and analyse the resulting data for the aims of each study.')}</p></article></div>{link(pick(d,'Laboratuvar hizmetlerini konuşalım','Discuss laboratory services'),'contact.html','button navy')}</div></section>'''

def solution_choices(d):
 items=pick(d,[('software','Analiz ve raporlama','Dizileme veriniz var; işlenmesini, yorumlanmasını ve raporlanmasını istiyorsunuz.','Short-read ve long-read verileri için Gennext.'),('hardware','Kurum içi donanım','Analizleri kendi kurumunuzun altyapısında yürütmek istiyorsunuz.','İş yükünüze göre yapılandırılan Worker Node.'),('laboratory','Longevity laboratuvarı','Genetik ve epigenetik değerlendirmeler için laboratuvar çalışmasına ihtiyaç duyuyorsunuz.','Microarray ve Nanopore uzun okuma dizileme.'),('training','Uygulamalı eğitim','Varyant değerlendirme ve platform kullanımı konusunda bilgi edinmek istiyorsunuz.','Tıbbi genomik eğitimleri ve video kaynakları.')],[('software','Analysis & reporting','You have sequencing data and need processing, interpretation and reporting.','Gennext for short-read and long-read data.'),('hardware','On-site hardware','You want analyses to run within your institution’s infrastructure.','Worker Nodes configured for your workload.'),('laboratory','Longevity laboratory','You need laboratory work for genetic and epigenetic assessment.','Microarray and Nanopore long-read sequencing.'),('training','Practical training','You want to develop skills in variant assessment and platform use.','Medical genomics courses and video resources.')])
 return '<div class="solution-choices">'+''.join(f'<a class="solution-choice" href="solutions.html#{key}"><span>0{i+1} ↗</span><h3>{title}</h3><p>{need}</p><strong>{output}</strong></a>' for i,(key,title,need,output) in enumerate(items))+'</div>'

def sequencing(d):
 items=pick(d,[('SHORT-READ','Kısa okuma analizleri','Panel, ekzom ve tüm genom dizileme verilerinin işlenmesi; varyantların filtrelenmesi, yorumlanması ve raporlanması.'),('LONG-READ','Uzun okuma analizleri','Uzun okuma dizileme verilerinin işlenmesi ve değerlendirilmesi. Analiz kapsamı, veri türü ve araştırma sorusuna göre belirlenir.')],[('SHORT-READ','Short-read analysis','Processing of panel, exome and whole-genome sequencing data, with variant filtering, interpretation and reporting.'),('LONG-READ','Long-read analysis','Processing and assessment of long-read sequencing data. Analysis scope is defined by the data type and research question.')])
 return '<div class="sequencing-options">'+''.join(f'<article><span>{tag}</span><h3>{title}</h3><p>{desc}</p></article>' for tag,title,desc in items)+'</div>'

def solutions(d,p):
 clinical=pick(d,[('Somatik analiz','Onkoloji ve moleküler patoloji','Tümör dizileme verilerinden varyant, füzyon ve biyobelirteç bulgularının değerlendirilmesi; uzman incelemesini destekleyen raporlama.'),('Germline analiz','Kalıtsal hastalıklar ve üreme sağlığı','Nadir hastalıklar, taşıyıcılık ve farmakogenetik çalışmalarında varyantların klinik bağlamda değerlendirilmesi.'),('Longevity','Genetik ve epigenetik değerlendirme','Sağlık, beslenme, spor ve cilt alanlarında genetik yatkınlık profilleri; epigenetik yaş değerlendirmeleri. Sağlık profesyonellerinin kişiselleştirilmiş danışmanlığına yönelik raporlar.')],[('Somatic analysis','Oncology and molecular pathology','Assessment of variants, fusions and biomarkers from tumour sequencing data, with reports supporting specialist review.'),('Germline analysis','Inherited conditions and reproductive health','Variant assessment in the clinical context of rare disease, carrier screening and pharmacogenetic studies.'),('Longevity','Genetic and epigenetic assessment','Genetic predisposition profiles across health, nutrition, sport and skin, alongside epigenetic age assessments. Reports support personalised professional guidance.')])
 cards=''.join(f'<article><p class="eyebrow">{a}</p><h3>{b}</h3><p>{c}</p></article>' for a,b,c in clinical)
 topics=''.join(f'<article class="topic"><h3>{a}</h3><ul>'+''.join(f'<li>{x}</li>' for x in b)+'</ul></article>' for a,b in d['trainingtopics'])
 return f'''<main id="main">{innerhero(d,pick(d,'İhtiyacınıza uygun<br>çözümü bulun.','Find the solution<br>that fits your needs.'),d['solutionslead'],'solutions')}<section class="section"><div class="container">{solution_choices(d)}</div></section><section class="section product-band" id="software"><div class="container"><div class="section-head"><div><p class="eyebrow">01 / GENNEXT</p><h2>{pick(d,'Dizileme verisinden<br>değerlendirilebilir bulgulara.','Sequencing data.<br>Findings you can assess.')}</h2></div><p>{d['softwarebody']}</p></div>{screen(d,p)}{sequencing(d)}<div class="clinical-options">{cards}</div><p class="scope-note">{pick(d,'Longevity raporları kişiselleştirilmiş sağlık danışmanlığını destekler; tanı testi değildir.','Longevity reports support personalised health guidance; they are not diagnostic tests.')}</p><div class="solution-actions">{link(d['demobtn'],'contact.html','button navy')}{link(d['brochure'],p+'assets/gennext-somatic-'+('en' if d['home']=='Home' else 'tr')+'.pdf',external=True)}</div></div></section><section class="section" id="hardware"><div class="container"><div class="hardware-split"><div><p class="eyebrow">02 / WORKER NODE</p><h2>{pick(d,'Analiz altyapınız,<br>kurumunuzun içinde.','Your analysis infrastructure.<br>At your institution.')}</h2><p>{d['hardwarebody']}</p><ul class="hardware-points"><li>{pick(d,'Örnek hacmi ve eş zamanlı analiz ihtiyacına göre kapasite','Capacity planned for sample volume and concurrent workloads')}</li><li>{pick(d,'Hesaplama ve depolama kaynaklarının birlikte planlanması','Coordinated computing and storage planning')}</li><li>{pick(d,'Mevcut altyapıya uygun kurulum','Deployment suited to existing infrastructure')}</li></ul>{link(d['hardwarebtn'],'contact.html','button navy')}</div>{hardware(d,p)}</div><div class="hardware-architecture">{diagram(d)}<div><h3>{pick(d,'Yerel işleme, merkezî koordinasyon','Local processing, central coordination')}</h3><p>{d['archdesc']}</p></div></div></div></section>{laboratory(d,p)}<section class="section" id="training"><div class="container"><p class="eyebrow">04 / {d['fields'][2]}</p><h2>{d['services'][2][0]}</h2><p class="training-intro">{d['trainingbody']}</p><div class="training-topics">{topics}</div>{link(d['trainingbtn'],'contact.html','button navy')}</div></section>{community(d,p)}{cta(d)}</main>'''

REFERENCE_GROUPS=[('Germline',['Acıbadem Mehmet Ali Aydınlar Üniversitesi · ACURARE','Marmara Üniversitesi','Ege Üniversitesi','Ümraniye Eğitim ve Araştırma Hastanesi']),('Somatik / Somatic',['İstgen Genetik Hastalıklar Değerlendirme Merkezi','Kocaeli Üniversitesi · Tıbbi Genetik','Süleyman Demirel Üniversitesi · Tıbbi Patoloji']),('Longevity',['Acıbadem Life','RootWell','AlbertHealth','Özel Doktor Terziler Kliniği','Dripfy','WeHealth','UPlife','Nuen Clinic','Dr. Nurcivan Ünsal Üz','Portakal Klinik','3D1K','SportoTeam','GenomiColor','Prof. Dr. Murat Baş','Doç. Dr. Demet Akpolat','Dr. Muhammet İkbal Bakırcı'])]
PUBS=[
('article','Rapid genome sequencing for critically ill infants: an inaugural pilot study from Turkey','Guner Yilmaz et al. · Frontiers in Pediatrics · 2024','VCF anotasyonu','VCF annotation','https://doi.org/10.3389/fped.2024.1412880'),
('article','Genetic heterogeneity in childhood leukemia/lymphoma: a Turkish cohort with strong predisposition','Onder et al. · Frontiers in Genetics · 2025','Veri işleme, anotasyon ve varyant filtreleme','Data processing, annotation and variant filtering','https://doi.org/10.3389/fgene.2025.1624306'),
('article','Unmasking genetic etiologies in neurodevelopmental disorders characterized by Cerebral Palsy: insights from integrative genomic approaches','Yigit et al. · Frontiers in Neurology · 2026','Dizileme verilerinin işlenmesi ve varyant anotasyonu','Sequencing-data processing and variant annotation','https://doi.org/10.3389/fneur.2026.1742186'),
('article','Integrative and systematic genomic approaches to improve diagnosis in rare and undiagnosed diseases: results from the RareBoost project','Yigit et al. · European Journal of Human Genetics · 2026','İş akışlarına atıf; genomik ve transkriptomik hizmet katkısı','Workflow citations; genomic and transcriptomic service contributions','https://doi.org/10.1038/s41431-026-02177-9'),
('preprint','Undiagnosed Diseases Program-Istanbul (UDP-IST): Diagnostic Impact of Systematic Genomic Reanalysis with Deep Phenotyping in 121 Patients','Akgun-Dogan et al. · Research Square · 2026','GenNext ile genomik yeniden analiz','GenNext workflow for genomic reanalysis','https://doi.org/10.21203/rs.3.rs-8842818/v1'),
('abstract','Determining molecular background of a group of childhood leukemia/lymphoma patients with positive family history from Türkiye','Önder et al. · HemaSphere · 2023 · PB2401','Anotasyon ve filtreleme','Annotation and filtering','https://pmc.ncbi.nlm.nih.gov/articles/PMC10429261/'),
('abstract','GenNext: Next-Generation Analysis Platform for Next-Generation Sequencing Data','Ergun et al. · TÜSEB Dergisi · 2024 · 7(Suppl-1), 33–34','Platform ve merkeziyetsiz mimari','Platform and decentralised architecture','https://tusebjournal.org/pdf/e92af88c-e19e-4edc-9ffc-eda5f1b4ae56/articles/tuseb-80/2024-Ek-1.pdf#page=33')]
def references(d,p):
 groups=''.join(f'<article class="reference-group"><h3>{group}</h3><ul>'+''.join(f'<li>{name}</li>' for name in names)+'</ul></article>' for group,names in REFERENCE_GROUPS)
 pubs=''
 for kind,title,meta,tr,en,url in PUBS:
  label=pick(d,{'article':'Hakemli makale','preprint':'Ön baskı','abstract':'Bildiri özeti'}[kind],{'article':'Peer-reviewed article','preprint':'Preprint','abstract':'Conference abstract'}[kind])
  pubs+=f'<article class="publication"><span class="pub-type">{label}</span><div><h3><a href="{url}" target="_blank" rel="noopener">{escape(title)} ↗</a></h3><p>{meta}</p><small>Gennext: {pick(d,tr,en)}</small></div></article>'
 return f'''<main id="main">{innerhero(d,pick(d,'Kurumlarla birlikte.<br>Bilimsel çalışmaların içinde.','Working with institutions.<br>Contributing to research.'),pick(d,'Klinik genomik ve longevity alanındaki referanslarımız ile Gennext’in kullanıldığı bilimsel çalışmalardan seçkiler.','Our clinical genomics and longevity references, alongside selected scientific studies using Gennext.'),'references')}<section class="section"><div class="container"><p class="eyebrow">{pick(d,'ÇALIŞTIĞIMIZ KURUMLAR VE PROFESYONELLER','INSTITUTIONS & PROFESSIONALS')}</p><h2>{pick(d,'Farklı ihtiyaçlar,<br>ortak çalışma alanları.','Different needs.<br>Shared areas of work.')}</h2><div class="reference-groups">{groups}</div></div></section><section class="section product-band" id="publications"><div class="container"><p class="eyebrow">{pick(d,'BİLİMSEL YAYINLAR','SCIENTIFIC PUBLICATIONS')}</p><h2>{pick(d,'Araştırmalarda Gennext','Gennext in research')}</h2><p class="publication-intro">{pick(d,'Bu çalışmalar Gennext’in araştırmaya özgü kullanımını ve katkılarını gösterir. Yayın sonuçları platform performansı için genel bir ölçüt değildir.','These studies document study-specific use and contributions. Their outcomes are not general benchmarks of platform performance.')}</p>{pubs}</div></section>{cta(d)}</main>'''

def evidence_teaser(d):
 return f'<section class="section evidence-teaser"><div class="container"><p class="eyebrow">{pick(d,"REFERANSLAR VE YAYINLAR","REFERENCES & PUBLICATIONS")}</p><h2>{pick(d,"Klinik uygulamada ve araştırmada.","In clinical practice and research.")}</h2><p>{pick(d,"Üniversiteler, genetik tanı merkezleri ve longevity alanında çalışan sağlık profesyonelleriyle farklı ihtiyaçlara yönelik çalışmalar yürütüyoruz.","We work with universities, genetic diagnostic centres and longevity professionals across different areas of need.")}</p><div class="reference-preview"><span>Acıbadem Üniversitesi · ACURARE</span><span>Marmara Üniversitesi</span><span>Ege Üniversitesi</span><span>İstgen</span></div>{link(pick(d,"Kurumları ve yayınları inceleyin","Explore references and publications"),"references.html")}</div></section>'

def home(d,p):
 s=base_home(d,p)
 import re
 s=re.sub(r'<div class="services-grid">.*?</div></div></section>',solution_choices(d)+'</div></section>',s,count=1,flags=re.S)
 s=s.replace('{never}', '')
 s=s.replace(omics(d),omics(d)+laboratory(d,p,True))
 s=s.replace(cta(d),evidence_teaser(d)+cta(d))
 return s

def about(d,p):return base_about(d,p).replace(cta(d),laboratory(d,p)+evidence_teaser(d)+cta(d))
# Conceptual product presentation replaces the screenshot dialog throughout.
def dialog(d,p):return ''
RENDERERS.update({'index':home,'solutions':solutions,'about':about,'references':references})
